import { afterEach, beforeEach, describe, it, expect, vi } from 'vitest'
import { FsmEngine, FsmEngineUnhandledEventError, FsmEngineUnknownEventError, FsmEngineUnknownTransitionStateError, FsmEngineUnreachableTransitionError, FsmEngineUnreachableStateError, FsmEngineMultipleStateDefinitionsError, FsmEngineMultipleEventDefinitionsError, FsmEngineNoDefinitionError, FsmEngineUnknownInitialStateError } from '../src'

type TestState = 'idle' | 'a' | 'b'

type TestEvents = {
  go:      undefined
  tick:    undefined
  guarded: { ok: boolean }
  value:   number
}

type TestContext = {
  count: number
  seen: string[]
}

describe('FsmEngine', () => {

  let context: TestContext
  let log: string[]

  beforeEach(() => {
    context = { count: 0, seen: [] }
    log = []
  })

  function logTransition(params: { event: string, meta: { fromState: string, toState: string, transitionKind: string } }): void {
    const { event, meta } = params
    const isInternal = meta.transitionKind === 'internal'
    if (isInternal && meta.fromState !== meta.toState) throw new Error('internal transition with different fromState and toState')
    const destination = isInternal ? '<-@' : `->${meta.toState}`
    log.push(`${meta.fromState}:${event}${destination}`)
  }

  function logBegin(params: { event: string, meta: { state: string } }): void {
    const { event, meta } = params
    log.push(`begin@${meta.state}:${event}`)
  }

  function logEnter(params: { state: string, meta: { cause: 'initial' | 'transition', event?: string, fromState?: string } }): void {
    const { state, meta } = params
    const origin = meta.cause === 'initial' ? 'initial' : `${meta.event}<-${meta.fromState}`
    log.push(`enter ${state}:${origin}`)
  }

  function logExit(params: { state: string, meta: { event: string, toState: string } }): void {
    const { state, meta } = params
    log.push(`exit ${state}:${meta.event}->${meta.toState}`)
  }


  describe('with guards', () => {
    it('runs actions and transitions state on first matching transition', () => {
      const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
        b.state('idle', s => {
          s.event('guarded', e => {
            e.when(({ payload }) => payload.ok).toState('a', t => {
              t.action(logTransition)
              t.action(({ context }) => context.seen.push('T1'))
            })
            e.toState('b', t => {
              t.action(logTransition)
              t.action(({ context }) => context.seen.push('T2'))
            })
          })
        })
        b.state('a')
        b.state('b')
      })

      const fsm = make({ context })

      fsm.dispatch('guarded', { ok: true })
      expect(log).toEqual(['idle:guarded->a'])
      expect(context.seen).toEqual(['T1'])
    })

    it('handles multiple guards on a transition', () => {
      const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
        b.state('idle', s => {
          s.event('guarded', e => {
            e.when(({ payload }) => payload.ok).when(() => false).toState('a', t => {
              t.action(logTransition)
              t.action(({ context }) => context.seen.push('T1'))        
            })
            e.toState('b', t => {
              t.action(logTransition)
              t.action(({ context }) => context.seen.push('T2'))
            })
          })
        })
        b.state('a')
        b.state('b')
      })
      const fsm = make({ context })
      fsm.dispatch('guarded', { ok: true })
      expect(log).toEqual(['idle:guarded->b'])
      expect(context.seen).toEqual(['T2'])
    })

    it('runs trailing unguarded transition if no guards match', () => {
      const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
        b.state('idle', s => {
          s.event('guarded', e => {
