            e.when(() => false).toState('a', t => t.action(logTransition))
            e.toState('b', t => t.action(logTransition))
          })
        })
        b.state('a')
        b.state('b')
      })

      const fsm = make({ context })

      fsm.dispatch('guarded', { ok: false })
      expect(log).toEqual(['idle:guarded->b'])
    })

    it('defaults to stay() if no guards match and no unguarded transition exists', () => {
