    })

    it('timer() dispatches a future event', () => {
      vi.useFakeTimers()

      type S = 'idle' | 'a'
      type E = { go: undefined, tick: undefined }
      type C = { seen: string[] }

      const make = FsmEngine.define<S, E, C>(b => {
        b.state('idle', s => {
          s.event('go', e => {
            e.toState('a', t => t.action(({ fsm, context }) => {
              fsm.timer({ key: 't', event: 'tick', ms: 100 })
