  describe('re-entrant dispatch', () => {

    it('queues re-entrant dispatches and processes them FIFO after the current event completes', () => {
      type S = 'idle' | 'a' | 'b'
      type E = { go: void, tick: void }
      type C = Record<string, never>

      const make = FsmEngine.define<S, E, C>(b => {
        b.state('idle', s => {
          s.event('go', e => {
            e.toState('a', t => {
              t.action(({ fsm }) => fsm.dispatch('tick')) // re-entrant while still processing go
              t.action(({ fsm }) => fsm.dispatch('tick')) // re-entrant while still processing go
              t.action(logTransition)
            })
          })
        })
        b.state('a', s => {
          s.event('tick', e => e.toState('b', t => t.action(logTransition)))
        })
        b.state('b', s => {
          s.event('tick', e => e.stay(t => t.action(logTransition)))
        })
      })

      const fsm = make({ context: {} })

      fsm.dispatch('go')

      expect(log).toEqual([
        'idle:go->a',
        'a:tick->b',
        'b:tick<-@',
      ])
    })

    it('queues re-entrant dispatches from a guard', () => {
      type S = 'idle' | 'a' | 'b'
      type E = { go: void, tick: void }
      type C = Record<string, never>

      const make = FsmEngine.define<S, E, C>(b => {
        b.state('idle', s => {
          // tick from idle goes to b
          s.event('tick', e => e.toState('b', t => t.action(logTransition)))

          // go intends to go to a, but its guard dispatches tick re-entrantly
          s.event('go', e => {
            e.when(() => {
              fsm.dispatch('tick') // re-entrant while still evaluating guards for go
              return true
            }).toState('a', t => t.action(logTransition))
          })
        })

        b.state('a', s => {
          s.event('tick', e => e.stay(t => t.action(logTransition)))
        })

        b.state('b')
      })

      const fsm = make({ context: {} })

      fsm.dispatch('go')

      // expect the 'go' transition to run first into state a, then the guard's 'tick' event handled in state a
      expect(log).toEqual([
        'idle:go->a',
        'a:tick<-@',
      ])
    })

    it('clears queued events if an event throws (queued events do not run)', () => {
      type S = 'idle'
      type E = { boom: { throw: boolean }, queued: void }
      type C = Record<string, never>

      const make = FsmEngine.define<S, E, C>(b => {
        b.state('idle', s => {
          s.event('boom', e => {
            e.stay(t => {
              t.action(({ fsm }) => fsm.dispatch('queued')) // should be enqueued, not run now
              t.action(({ payload }) => {
                if (payload.throw) throw new Error('boom')    // causes dispatch to abort
              })
              t.action(logTransition)
            })
          })
          s.event('queued', e => e.stay(t => t.action(logTransition)))
        })
      })

      const fsm = make({ context: {} })

      fsm.dispatch('boom', { throw: false })
      expect(log).toEqual([
        'idle:boom<-@',
        'idle:queued<-@', // queued event runs when boom does not throw
      ])
      log = []
      expect(() => fsm.dispatch('boom', { throw: true })).toThrow(/boom/)
      expect(log).toEqual([]) // queued event did not run a second time
    })

  })


