describe('Union action types', () => {
  // These are compile-time tests to make sure that the public action
  // types that are unions of multiple specific action types (e.g.
  // FsmAction) are assignable to the narrower types inferred by the DSL

  type TestEvent = keyof TestEvents
  type TestAction = FsmAction<TestState, TestEvents, TestEvent, TestContext>
  type TestStateAction = FsmStateAction<TestState, TestEvents, TestEvent, TestContext>
  type TestEventAction = FsmEventAction<TestState, TestEvents, TestEvent, TestContext>

  // --- reusable actions (compile-time shape checks) ---

  const eventLog: TestEventAction = ({ event, meta }) => 'state' in meta ? logBegin({ event, meta }) : logTransition({ event, meta })
  const stateLog: TestStateAction = ({ state, meta }) => 'cause' in meta ? logEnter({ state, meta }) : logExit({ state, meta })
  const actionLog = (label: string): TestAction => ({ context }) => { log.push(`${label} context count:${context.count++}`) }

  // payload typing checks
  const valueLog: FsmEventAction<TestState, TestEvents, 'value', TestContext> = ({ payload }) => {
    const n: number = payload
    log.push(`value:${n}`)
  }

  const tickLog: FsmEventAction<TestState, TestEvents, 'tick', TestContext> = ({ payload }) => {
    const _u: undefined = payload
    log.push('tick')
  }

  // --- usage tests ---

  it('accepts reusable FsmEventAction and FsmStateAction in all matching action slots', () => {
    const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
      b.state('idle', s => {
        s.onEnter(stateLog)
        s.onExit(stateLog)

        s.event('tick', e => {
          e.begin(eventLog)
          e.toState('a', t => t.action(eventLog))
        })
      })

      b.state('a', s => s.onEnter(stateLog))
    })
    make({ context }).dispatch('tick')
    expect(log).toEqual([
      'enter idle:initial',
      'begin@idle:tick',
      'exit idle:tick->a',
      'idle:tick->a',
      'enter a:tick<-idle',
    ])
  })

  it('accepts reusable FsmAction in all action slots', () => {
    const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
      b.state('idle', s => {
        s.onEnter(actionLog('enter idle'))
        s.onExit(actionLog('exit idle'))

        s.event('tick', e => {
          e.begin(actionLog('begin tick'))
          e.toState('a', t => t.action(actionLog('transition to a')))
        })
      })

      b.state('a', s => s.onEnter(actionLog('enter a')))
    })
    make({ context }).dispatch('tick')
    expect(log).toEqual([
      "enter idle context count:0",
      "begin tick context count:1",
      "exit idle context count:2",
      "transition to a context count:3",
      "enter a context count:4",
    ])
  })


  it('preserves payload typing for valued events', () => {
    const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
      b.state('idle', s => s.event('value', e => e.stay(t => t.action(valueLog))))
    })
    make({ context }).dispatch('value', 42)
    expect(log).toEqual(['value:42'])
  })

  it('preserves payload typing for payloadless events', () => {
    const make = FsmEngine.define<TestState, TestEvents, TestContext>(b => {
      b.state('idle', s => s.event('tick', e => e.stay(t => t.action(tickLog))))
    })
    make({ context }).dispatch('tick')
    expect(log).toEqual(['tick'])
  })
})

